INSERT INTO public.education_stages (id, name, code, order_index, created_at, updated_at) SELECT gen_random_uuid(), 'Primary', 'PRIMARY', 1, now(), now() WHERE NOT EXISTS (SELECT 1 FROM public.education_stages WHERE code = 'PRIMARY');
INSERT INTO public.education_stages (id, name, code, order_index, created_at, updated_at) SELECT gen_random_uuid(), 'Preparatory', 'PREPARATORY', 2, now(), now() WHERE NOT EXISTS (SELECT 1 FROM public.education_stages WHERE code = 'PREPARATORY');
