INSERT INTO public.education_grades (id, stage_id, name, code, order_index, created_at, updated_at) SELECT gen_random_uuid(), s.id, 'Grade 1', 'P1', 1, now(), now() FROM public.education_stages s WHERE s.code = 'PRIMARY' AND NOT EXISTS (SELECT 1 FROM public.education_grades WHERE code = 'P1');
