INSERT INTO public.education_tracks (id, stage_id, grade_id, name, code, created_at, updated_at) SELECT gen_random_uuid(), s.id, g.id, 'Medicine & Life Sciences', 'MED', now(), now() FROM public.education_stages s JOIN public.education_grades g ON g.stage_id = s.id WHERE s.code = 'BACCALAUREATE' AND g.code = 'BACC_3' AND NOT EXISTS (SELECT 1 FROM public.education_tracks WHERE code = 'MED');
