-- 1.2F Verified Egyptian Education Taxonomy Seed (idempotent)
-- Verify counts (admin execution)
SELECT 'stages', COUNT(*) FROM public.education_stages WHERE code IN ('PRIMARY','PREPARATORY','SECONDARY','BACCALAUREATE');
SELECT 'grades' FROM public.education_grades WHERE stage_id IN (SELECT id FROM public.education_stages WHERE code IN ('PRIMARY','PREPARATORY','SECONDARY','BACCALAUREATE')) GROUP BY stage_id;
SELECT 'tracks' FROM public.education_tracks WHERE stage_id IN (SELECT id FROM public.education_stages WHERE code='BACCALAUREATE');
